// Auto-generated Form Components
// Generated by Builder Layer 04

import React from 'react';
import {
  Box, Button, Grid, Typography, Card, CardContent, CardActions,
  IconButton, Table, TableBody, TableCell, TableContainer, TableHead,
  TableRow, Paper
} from '@mui/material';
import { Add, Delete, MoveUp, MoveDown } from '@mui/icons-material';
import { FieldFactory } from './FieldFactory';
import { useFormState } from './hooks';

// ============================================================================
// AutoForm - Generate form from field definitions
// ============================================================================

interface FieldDef {
  name: string;
  label?: string;
  type?: string;
  required?: boolean;
  options?: Array<{ value: any; label: string }>;
  [key: string]: any;
}

interface AutoFormProps {
  fields: FieldDef[];
  values?: Record<string, any>;
  onSubmit: (data: Record<string, any>) => void;
  onChange?: (data: Record<string, any>) => void;
  readonly?: boolean;
  columns?: number;
}

export const AutoForm: React.FC<AutoFormProps> = ({
  fields,
  values = {},
  onSubmit,
  onChange,
  readonly = false,
  columns = 2
}) => {
  const { values: formValues, handleChange, errors } = useFormState(values);

  React.useEffect(() => {
    onChange?.(formValues);
  }, [formValues]);

  const handleFormSubmit = () => {
    onSubmit(formValues);
  };

  return (
    <Box>
      <Grid container spacing={2}>
        {fields.map((field) => (
          <Grid item xs={12} md={12 / columns} key={field.name}>
            <Typography variant="caption" color="text.secondary">
              {field.label}
              {field.required && (
                <Typography component="span" color="error">
                  {' '}
                  *
                </Typography>
              )}
            </Typography>
            <FieldFactory
              type={field.type}
              value={formValues[field.name]}
              onChange={(v) => handleChange(field.name, v)}
              options={field.options}
              disabled={readonly}
              error={!!errors[field.name]}
              helperText={errors[field.name]}
            />
          </Grid>
        ))}
      </Grid>
      {!readonly && (
        <Box display="flex" gap={1} justifyContent="flex-end" mt={3}>
          <Button type="button" onClick={handleFormSubmit} variant="contained">
            Save
          </Button>
        </Box>
      )}
    </Box>
  );
};

// ============================================================================
// FormArray - Dynamic array of items
// ============================================================================

interface FormArrayProps {
  label: string;
  template: FieldDef[];
  values?: any[];
  onChange?: (items: any[]) => void;
  readonly?: boolean;
  minItems?: number;
  maxItems?: number;
}

export const FormArray: React.FC<FormArrayProps> = ({
  label,
  template,
  values = [],
  onChange,
  readonly = false,
  minItems = 0,
  maxItems = 10
}) => {
  const [items, setItems] = React.useState(values);

  const handleAdd = () => {
    if (items.length < maxItems) {
      const newItem: Record<string, any> = {};
      template.forEach((f) => {
        newItem[f.name] = '';
      });
      const updated = [...items, newItem];
      setItems(updated);
      onChange?.(updated);
    }
  };

  const handleRemove = (index: number) => {
    if (items.length > minItems) {
      const updated = items.filter((_, i) => i !== index);
      setItems(updated);
      onChange?.(updated);
    }
  };

  const handleUpdate = (index: number, field: string, value: any) => {
    const updated = [...items];
    updated[index] = { ...updated[index], [field]: value };
    setItems(updated);
    onChange?.(updated);
  };

  return (
    <Card sx={{ mb: 2 }}>
      <CardContent>
        <Box
          display="flex"
          justifyContent="space-between"
          alignItems="center"
          mb={2}
        >
          <Typography variant="subtitle1">
            {label} ({items.length})
          </Typography>
          {!readonly && (
            <Button
              size="small"
              startIcon={<Add />}
              onClick={handleAdd}
              disabled={items.length >= maxItems}
            >
              Add
            </Button>
          )}
        </Box>

        {items.length === 0 ? (
          <Typography variant="body2" color="text.secondary">
            No items
          </Typography>
        ) : (
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  {template.map((f) => (
                    <TableCell key={f.name} sx={{ fontWeight: 'bold' }}>
                      {f.label}
                    </TableCell>
                  ))}
                  {!readonly && <TableCell width={60}>Actions</TableCell>}
                </TableRow>
              </TableHead>
              <TableBody>
                {items.map((item, i) => (
                  <TableRow key={i}>
                    {template.map((f) => (
                      <TableCell key={f.name}>
                        <FieldFactory
                          type={f.type}
                          value={item[f.name]}
                          onChange={(v) => handleUpdate(i, f.name, v)}
                          options={f.options}
                          disabled={readonly}
                          size="small"
                        />
                      </TableCell>
                    ))}
                    {!readonly && (
                      <TableCell>
                        <IconButton
                          size="small"
                          onClick={() => handleRemove(i)}
                          disabled={items.length <= minItems}
                        >
                          <Delete fontSize="small" />
                        </IconButton>
                      </TableCell>
                    )}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}
      </CardContent>
    </Card>
  );
};
